#!/usr/bin/env bash
set -euo pipefail

# grompp
(cd ../../.. && env GMX_DISABLE_MODULAR_SIMULATOR=1 OMP_NUM_THREADS=1 ../../../build_gateb_cuda/bin/gmx grompp -f ../../../tests/reference_results/gate_h_neutral_scaffold_bringup/inputs/exact_respa_short.mdp -c ../../../tests/reference_results/gate_h_fixture_scaffold/gate_h_dense_oligomer_2x2x2/generated/system.gro -p ../../../tests/reference_results/gate_h_fixture_scaffold/gate_h_dense_oligomer_2x2x2/generated/topol.top -o ../../../tests/reference_results/gate_h_neutral_scaffold_bringup/inputs/exact_respa_short.tpr -po ../../../tests/reference_results/gate_h_neutral_scaffold_bringup/inputs/mdout.mdp -maxwarn 1 > ../../../tests/reference_results/gate_h_neutral_scaffold_bringup/logs/grompp.stdout 2> ../../../tests/reference_results/gate_h_neutral_scaffold_bringup/logs/grompp.stderr)

# mdrun_cpu
