# mdrun_gpu
(cd ../../.. && env GMX_DISABLE_MODULAR_SIMULATOR=1 GMX_EXACT_RESPA_RUNTIME_EVENT_TRACE_FILE=../../../tests/reference_results/gate_h_neutral_scaffold_bringup/gpu/event_trace.tsv GMX_EXACT_RESPA_TOTAL_FORCE_DUMP_FILE=../../../tests/reference_results/gate_h_neutral_scaffold_bringup/gpu/total_force.tsv GMX_PCFF_RESPA_MERGE_TRACE_DIR=../../../tests/reference_results/gate_h_neutral_scaffold_bringup/gpu/merge_trace OMP_NUM_THREADS=1 ../../../build_gateb_cuda/bin/gmx mdrun -s ../../../tests/reference_results/gate_h_neutral_scaffold_bringup/inputs/exact_respa_short.tpr -deffnm ../../../tests/reference_results/gate_h_neutral_scaffold_bringup/gpu/run -ntmpi 1 -ntomp 1 -dlb no -nb gpu -pme gpu -bonded gpu -update gpu -pin off > ../../../tests/reference_results/gate_h_neutral_scaffold_bringup/logs/mdrun_gpu.stdout 2> ../../../tests/reference_results/gate_h_neutral_scaffold_bringup/logs/mdrun_gpu.stderr)
